import{_ as o,o as s,c as t,a2 as a}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-033 — Program rosters: a row that names an entry links to it, hardware lists are filled, episodes sit under Milestones","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-033-program-roster-links-and-milestones.md","filePath":"uxs/decisions/UXD-033-program-roster-links-and-milestones.md"}'),r={name:"uxs/decisions/UXD-033-program-roster-links-and-milestones.md"};function i(n,e,d,l,c,h){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="uxd-033-—-program-rosters-a-row-that-names-an-entry-links-to-it-hardware-lists-are-filled-episodes-sit-under-milestones" tabindex="-1">UXD-033 — Program rosters: a row that names an entry links to it, hardware lists are filled, episodes sit under Milestones <a class="header-anchor" href="#uxd-033-—-program-rosters-a-row-that-names-an-entry-links-to-it-hardware-lists-are-filled-episodes-sit-under-milestones" aria-label="Permalink to &quot;UXD-033 — Program rosters: a row that names an entry links to it, hardware lists are filled, episodes sit under Milestones&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by unit tests, e2e on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed 2026-11-13, decided and built)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-13-slice-E2-brief.md</code> §12 approved as written (E-decisions 5a, 6a, 7a, 8a, 9a, &quot;approved all E-series recommendations&quot;)</li><li><strong>Answers</strong>: PG7, PG8, PG9 of the UX feedback plan; slice E2</li><li><strong>Builds on</strong>: <a href="./UXD-032-program-page-card-rails-and-compact-hardware">UXD-032</a> (the sections and cards of the page)</li><li><strong>Changes</strong>: <code>static/data/programs/*.json</code> (33 files), <code>src/types/program.ts</code> (<code>ProgramRosterLink</code>, <code>link</code>, <code>milestone</code>), <code>src/lib/program-page.ts</code> (<code>milestoneRows</code>, <code>rowPath</code>, the <code>milestones</code> section), <code>src/routes/programs/[id]/+page.svelte</code>, <code>+page.server.ts</code>, <code>+page.ts</code>, <code>static/data/schemas/program.schema.json</code>, <code>messages/*.json</code> (<code>program_section_milestones</code>), <code>src/lib/programs-roster.test.ts</code> (new), <code>tests/e2e/programs-roster.spec.ts</code> (new)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Of 291 roster rows, 109 named something without linking to it. 14 of those named an entry that exists (Apollo 1, 7 and 9, Huygens, Viking 1, Mariner 10; Challenger, Columbia, Compton, Gaia, Euclid, Viking 2, N1, Columbus). Nine programs had no hardware row though the fleet holds their craft (Cassini, Voyager, Pioneer, Galileo, New Horizons, the Mars rovers). Cassini&#39;s &quot;four missions&quot; were one mission and three segments, and 56 of 126 missions sat in no roster.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>A row that names an existing entry links to it (5a).</strong> A name-only row about a mission becomes a linked row (<code>linked_id</code> + <code>ref: mission</code>, year and note kept). A name-only row about a craft or a station module keeps its name, year and note and gains <code>link: { ref: &#39;fleet&#39; | &#39;module&#39;, id, station? }</code>; a module link names its station (<code>iss</code> | <code>tiangong</code>), so Columbus under <code>esa-human</code> opens <code>/iss?module=columbus</code>. <code>rowPath(programId, row)</code> builds the path for every row kind. Flights of a craft (Gemini 1, Shenzhou 5, Lunar Orbiter) stay context: they are flights, not the craft.</li><li><strong>Hardware is what the program&#39;s missions flew (6a).</strong> A fleet entry reached through a linked mission&#39;s <code>fleet_refs</code> is a hardware row if it is a launcher, a spacecraft, a lander, an orbiter or a rover; launch sites are left out. Sputnik, Commercial stations and ROS stay without hardware (Sputnik&#39;s rocket in the fleet is Vostok&#39;s R-7) and draw no Hardware section. The card&#39;s name is the entry&#39;s own, in the page&#39;s locale (<code>fleetNames</code>, from the server load), not a capitalised id.</li><li><strong>Missions that exist join the roster (7a).</strong> Luna 9, 10, 16, 17, 21 (Soviet lunar), Giotto, Rosetta, Juice, BepiColombo, SMART-1 (Ariane), Galileo, Ulysses, Magellan (Space Shuttle; the mission files name the Shuttle as vehicle), Mariner 4 and 9. Missions that do not exist (Kaguya, Chandrayaan-2, STS-1, Artemis I) are not added; they go to the content stream and the mission runbook.</li><li><strong>Milestones (9a).</strong> <code>milestone: true</code> marks a name-only row that is an episode, phase, decision or plan inside the program, not a flight, a craft or a test. It is drawn under a <strong>Milestones</strong> heading right after Missions (order: Missions, Milestones, On the surface, Hardware, Related programs, Go deeper, Sources), as the same timeline without a pane or a card; a program with no mission row draws only Milestones. A milestone row has no link.</li><li><strong>Mission rows show the mission&#39;s own name</strong> (<code>missionDetails[id].name</code>, localised) instead of a capitalised id (<code>viking1</code> read &quot;Viking1&quot;).</li><li><strong>Dispatch debt (8a).</strong> Linking does not wait for a dispatch; the targets that have none are on the deferred list (<code>docs/wip/2026-11-13-slice-E2-brief.md</code> §2.5 counts them).</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>One new key, <code>program_section_milestones</code>, in 14 locales, shown only where a program has milestones. The glossary has no entry for the word; each locale&#39;s form follows its existing &quot;historic milestone&quot; string.</li><li>Roster <code>name</code>, <code>role</code> and <code>note</code> stay English in every locale (unchanged).</li><li><code>programs-roster.test.ts</code> guards the data: every <code>linked_id</code> and <code>link</code> resolves, no name-only row equals an existing mission, craft or module name, no entry is listed twice in a program, every linked mission has a thumb, a milestone row names no entry.</li><li>A program whose earliest linked mission changed opens its pane on that mission (Apollo: Apollo 1).</li></ul>',8)])])}const u=o(r,[["render",i]]);export{g as __pageData,u as default};
